(()=>{var LANGS=["en","ja","zh","es","ru"];var META={en:{title:"lighthouse-badges — Lighthouse Score Badges from the CLI",description:"A CLI tool that generates Lighthouse score badges, JSON, or SVG donut charts using local Chrome and the Lighthouse npm package."},ja:{title:"lighthouse-badges — CLIで作るLighthouseスコアバッジ",description:"ローカルChromeとLighthouse npmパッケージを使い、Lighthouseスコアバッジ・JSON・SVGドーナツチャートを生成するCLIツール。"},zh:{title:"lighthouse-badges — 用 CLI 生成 Lighthouse 分数徽章",description:"使用本地 Chrome 和 Lighthouse npm 包生成 Lighthouse 分数徽章、JSON 或 SVG 环形图的命令行工具。"},es:{title:"lighthouse-badges — Insignias de puntuación Lighthouse desde la CLI",description:"Herramienta CLI que genera insignias de puntuación Lighthouse, JSON o gráficos de dona SVG usando Chrome local y el paquete npm Lighthouse."},ru:{title:"lighthouse-badges — Значки оценок Lighthouse из CLI",description:"Инструмент CLI для генерации значков оценок Lighthouse, JSON или SVG-диаграмм с помощью локального Chrome и npm-пакета Lighthouse."}};var root=document.documentElement;var ml=new MultilanguageJS({languages:LANGS,defaultLanguage:"en"});var langSelect=document.getElementById("lang-select");function applyMeta(lang){var m=META[lang]||META.en;document.title=m.title;var desc=document.querySelector('meta[name="description"]');if(desc)desc.setAttribute("content",m.description);}function setLanguage(lang){if(LANGS.indexOf(lang)===-1)lang="en";ml.setLanguage(lang);applyMeta(lang);root.setAttribute("lang",lang);if(langSelect)langSelect.value=lang;localStorage.setItem("lang",lang);}var storedLang=localStorage.getItem("lang");var browserLang=(navigator.language||"en").slice(0,2);setLanguage(storedLang||(LANGS.indexOf(browserLang)!==-1?browserLang:"en"));if(langSelect){langSelect.addEventListener("change",(e)=>setLanguage(e.target.value));}document.querySelectorAll(".copy-btn").forEach((btn)=>{btn.addEventListener("click",()=>{var code=btn.parentElement.querySelector("code");if(!code)return;navigator.clipboard.writeText(code.textContent).then(()=>{btn.classList.add("copied");setTimeout(()=>btn.classList.remove("copied"),1500);});});});})();
